def process(items):
    result = []
    seen_hashable = set()
    seen_unhashable = []

    for item in items:
        try:
            if item in seen_hashable:
                continue
        except TypeError:
            if item in result:
                continue
            seen_unhashable.append(item)
            result.append(item)
            continue

        if seen_unhashable and item in seen_unhashable:
            continue

        seen_hashable.add(item)
        result.append(item)

    return result

def process(items):
    result = []
    seen_hashable = {}
    seen_unhashable = []

    for item in items:
        try:
            item_hash = hash(item)
        except Exception:
            is_duplicate = False

            for existing in seen_unhashable:
                if existing == item:
                    is_duplicate = True
                    break

            if not is_duplicate:
                for bucket in seen_hashable.values():
                    for existing in bucket:
                        if existing == item:
                            is_duplicate = True
                            break
                    if is_duplicate:
                        break

            if not is_duplicate:
                result.append(item)
                seen_unhashable.append(item)

            continue

        bucket = seen_hashable.get(item_hash)
        is_duplicate = False

        if bucket is not None:
            for existing in bucket:
                if existing == item:
                    is_duplicate = True
                    break

        if not is_duplicate:
            for existing in seen_unhashable:
                if existing == item:
                    is_duplicate = True
                    break

        if not is_duplicate:
            result.append(item)
            if bucket is None:
                seen_hashable[item_hash] = [item]
            else:
                bucket.append(item)

    return result

def process(call, attempts=3):
    if attempts <= 0:
        raise ValueError("attempts must be positive")

    last_timeout = None
    for _ in range(attempts):
        try:
            return call()
        except TimeoutError as exc:
            last_timeout = exc

    raise last_timeout

def process(keys, fetch_many):
    if not keys:
        return []

    unique_keys = list(dict.fromkeys(keys))
    values = fetch_many(unique_keys)
    return [values.get(key) for key in keys]

